/** Existing schema1 actual coal/iron world, newly generated copper areas and retained original recognition. */
final class NativeCopperRuntime {
 static final String QUEST="kingdom_smp:miner/a03";
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(project.owner());h.assertTrue(p!=null,"Original paid Miner peer attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var data=NativeOreSavedData.get(server);h.assertTrue(server.getCommands().getDispatcher().execute("kingdom admin profession ores "+p.getGameProfile().getName(),server.createCommandSourceStack())==1,"Real OP2console inspects bounded native ore working areas");boolean commandDenied=false;try{server.getCommands().getDispatcher().execute("kingdom admin profession ores "+p.getGameProfile().getName(),p.createCommandSourceStack());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){commandDenied=true;}h.assertTrue(commandDenied,"Ordinary Miner cannot invoke administrator area diagnostics");
  if(track.completedQuestIds().contains(QUEST)){server.tickRateManager().setTickRate(20);h.assertTrue(track.xp()==500&&track.completedQuestIds().size()==5&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"coal")==65&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"iron")==48&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"copper")==65&&NativeOreQuests.count(p,QUEST)==64&&ConstructionService.structureIntact(level,project),"Actual second JVM retains old coal/iron/recognition plus precise new separate-area copper64of65/500XP/original Doran");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("NATIVE_COPPER_RESTART_PASSED: legacy64coal48iron recognition/spent records retained, actual new65coal65copper raw counters/64separate-area copper, canonical5earned500XP/original Mine-Doran survive restart without duplication");return;}
  h.assertTrue(track.xp()==400&&track.completedQuestIds().size()==4&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"coal")==64&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"iron")==48&&data.evidence().copper(p.getUUID(),ProfessionRank.APPRENTICE,2)==0,"Starts from actual legacy schema1 extraction/canonical400XP, no invented historical area ownership");var near=generated(h,p,144,128);var coal=near.stream().filter(pos->metric(p,pos).equals("coal")).findFirst().orElseThrow();long baseChunk=ChunkPos.asLong(coal.getX()>>4,coal.getZ()>>4);var mixed=near.stream().filter(pos->metric(p,pos).equals("copper")&&ChunkPos.asLong(pos.getX()>>4,pos.getZ()>>4)==baseChunk).findFirst().orElseThrow();mine(h,p,coal);mine(h,p,mixed);h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"coal")==65&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"copper")==1&&NativeOreQuests.count(p,QUEST)==0,"Actual copper in the coal working area cannot satisfy separate excavation; prior64coal remain intact");var far=generated(h,p,160,128).stream().filter(pos->metric(p,pos).equals("copper")).limit(64).toList();h.assertTrue(far.size()==64,"Actual new separate native copper seams contain full64required blocks");for(var at:far)mine(h,p,at);h.assertTrue(NativeOreQuests.count(p,QUEST)==64&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"copper")==65,"Exactly64distinct valid copper locations; mixed-area surplus cannot replace them");CreateCraftRuntime.counter(p,project);var q=ProfessionService.review(p,"quest:"+QUEST);ProfessionService.confirm(p,q.nonce());boolean denied=false;try{ProfessionService.review(p,"quest:"+QUEST);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(p.getUUID()).track(Profession.MINER).xp()==500,"Actual separate-area review earns100XPonce; missing descent/inspection still block rank");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(store.professions(p.getUUID())),"Canonical new copper award and original records reopen");var marker=new net.minecraft.nbt.CompoundTag();marker.putUUID("store",store.id());com.mohymods.kingdomsmp.persistence.AtomicNbt.write(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("native-copper-runtime-proof.nbt"),marker);com.mojang.logging.LogUtils.getLogger().info("NATIVE_COPPER_NATIVE_PASSED: original schema1 coal/iron/canonical400XP retained without retrospective area assignment, real new OreFeature coal/copper marks/66native correct-tool removals, same-area copper refusal/separate64copper/500earnedXP/replay refusal/original Doran; private future terrain/tools/mining-time only");
 }
 static String metric(ServerPlayer p,BlockPos pos){var mark=p.serverLevel().getChunkAt(pos).getData(NativeOreProvenance.MARKS).at(pos.asLong());return mark==null?"":NativeOreQuests.BLOCKS.getOrDefault(mark,"");}
 static List<BlockPos> generated(GameTestHelper h,ServerPlayer p,int x,int z)throws Exception{var level=p.serverLevel();var result=new ArrayList<BlockPos>();for(int dx=0;dx<2;dx++)for(int dz=0;dz<2;dz++){var chunk=level.getChunk(x+dx,z+dz);var at=new BlockPos((x+dx)*16,32,(z+dz)*16);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);if(chunk.hasData(NativeOreProvenance.MARKS))chunk.getData(NativeOreProvenance.MARKS).positions().stream().map(BlockPos::of).forEach(result::add);}result.sort(Comparator.comparingLong(BlockPos::asLong));h.assertTrue(!result.isEmpty(),"New genuine native decorated chunk generation supplies tracked ore");return result;}
 static void mine(GameTestHelper h,ServerPlayer p,BlockPos pos){BlacksmithRepairRuntime.near(p,pos);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));h.assertTrue(p.gameMode.destroyBlock(pos),"Real permitted native correct-tool extraction");}
}
